for i in I:
    if i not in supply:
        raise ValueError(f'Missing supply for {i}')
    if i not in cost:
        raise ValueError(f'Missing cost row for {i}')
    for j in J:
        if j not in cost[i]:
            raise ValueError(f'Missing cost for ({i},{j})')
for j in J:
    if j not in demand:
        raise ValueError(f'Missing demand for {j}')
m = gp.Model('Amazon_Distribution')
x = m.addVars(I, J, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[i][j] * x[i, j] for i in I for j in J)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[i, j] for i in I)) == demand[j] for j in J), name='')
m.addConstrs((gp.quicksum((x[i, j] for j in J)) <= supply[i] for i in I), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')